changeSet.sql:
UPDATE clinlims.delivery_channel d SET host = COALESCE(NULLIF(substring(e.uri from '://([^:/]+)'), ''), NULLIF(split_part(e.uri, ':', 1), '')), port = CAST(NULLIF(substring(e.uri from ':([0-9]+)/?$'), '') AS INTEGER), security = CASE CAST(NULLIF(substring(e.uri from ':([0-9]+)/?$'), '') AS INTEGER) WHEN 465 THEN 'SSL_TLS' WHEN 587 THEN 'STARTTLS' ELSE 'NONE' END, username = b.username, secret = b.password, last_updated = now() FROM clinlims.external_connection e LEFT JOIN clinlims.basic_authentication_data b ON b.external_connection_id = e.id WHERE d.channel = 'EMAIL' AND d.host IS NULL AND e.programmed_connection = 'SMTP_SERVER' AND e.active = true;
UPDATE clinlims.delivery_channel d SET host = e.uri, username = b.username, secret = b.password, last_updated = now() FROM clinlims.external_connection e LEFT JOIN clinlims.basic_authentication_data b ON b.external_connection_id = e.id WHERE d.channel = 'WHATSAPP' AND d.host IS NULL AND d.username IS NULL AND e.programmed_connection = 'WHATSAPP_SERVER' AND e.active = true;
UPDATE clinlims.external_connection SET active = false WHERE programmed_connection IN ('SMTP_SERVER', 'WHATSAPP_SERVER') AND active = true;

UPDATE clinlims.notification_payload_template SET subject_template = '[testName] results ready', message_template = '[testName] results are ready. Please contact your clinician or the laboratory.', last_updated = now() WHERE type = 'TEST_RESULT' AND message_template LIKE '[testName] testing results have been finalized for Patient%';
UPDATE clinlims.notification_payload_template SET message_template = 'Sample [sampleAccessionNumber] has been referred to [labName] for test [testName]. Referral id: [referralId].', last_updated = now() WHERE type = 'REFERRAL_OUT' AND message_template = 'Sample [sampleAccessionNumber] for patient [patientFirstName] [patientLastName] has been referred to [labName] for test [testName]. Referral id: [referralId].';
UPDATE clinlims.notification_payload_template SET message_template = 'Result for sample [sampleAccessionNumber] (test [testName]) returned by [labName] was rejected: [rejectReason]. Please re-collect and re-refer. Order: [deepLink]', last_updated = now() WHERE type = 'REFERRAL_REJECTED_NEEDS_RECOLLECTION' AND message_template = 'Result for sample [sampleAccessionNumber] (patient [patientFirstName] [patientLastName], test [testName]) returned by [labName] was rejected: [rejectReason]. Please re-collect and re-refer. Order: [deepLink]';
